// Medals for all 21 built-in story courses. Thresholds are per-course and use saved personal bests.
const medalTargets=[{"gold":10.5,"silver":13},{"gold":18,"silver":22},{"gold":11.5,"silver":14},{"gold":16.5,"silver":21.0},{"gold":25.5,"silver":27.5},{"gold":12.5,"silver":14.5},{"gold":11.5,"silver":14.5},{"gold":16.5,"silver":21.0},{"gold":12.0,"silver":15.5},{"gold":15.0,"silver":19.0},{"gold":37.5,"silver":39.5},{"gold":34,"silver":42},{"gold":19.0,"silver":24.5},{"gold":24.5,"silver":31.0},{"gold":24.5,"silver":31.0},{"gold":23.5,"silver":30.0},{"gold":24.5,"silver":31.0},{"gold":24.5,"silver":31.0},{"gold":24.5,"silver":31.0},{"gold":24.5,"silver":31.0},{"gold":21.0,"silver":27.0}];
medalTargets.push(...[{"gold":17.5,"silver":23.0},{"gold":19.5,"silver":26.0},{"gold":22.0,"silver":28.5},{"gold":20.5,"silver":27.0},{"gold":23.5,"silver":31.0},{"gold":23.0,"silver":30.0},{"gold":25.0,"silver":32.5},{"gold":26.5,"silver":34.5},{"gold":27.5,"silver":36.0}]);
function medalTargetFor(i){return STORY_COURSES[i]?.medalTargets||medalTargets[i];}
// Published story slots always award medals, including developer-edited maps.
function medalEligible(i){return Number.isInteger(i)&&i>=0&&i<STORY_VISIBLE_COUNT}
function medalTier(i){if(!medalEligible(i))return '';const t=data.storyTimes[i]?.best;if(Number.isFinite(t)&&t>0){const target=medalTargetFor(i);return t<=target.gold+1e-7?'gold':t<=target.silver+1e-7?'silver':'bronze'}return data.cleared.includes(i)?'bronze':''}
function medalWords(){return {ko:{gold:'금메달',silver:'은메달',bronze:'동메달',clear:'완주',target:'메달 목표',next:'까지',best:'최고 등급 달성',none:'미획득',pilot:'전체 21개 항로 메달'},en:{gold:'Gold',silver:'Silver',bronze:'Bronze',clear:'Finish the stage',target:'Medal targets',next:'to',best:'Highest medal earned',none:'Not earned',pilot:'Medals: all 21 courses'},ja:{gold:'金メダル',silver:'銀メダル',bronze:'銅メダル',clear:'ステージクリア',target:'メダル目標',next:'まで',best:'最高ランク獲得',none:'未獲得',pilot:'全21航路のメダル'},zh:{gold:'金牌',silver:'银牌',bronze:'铜牌',clear:'完成关卡',target:'奖牌目标',next:'还差',best:'已获得最高奖牌',none:'未获得',pilot:'全部21条航线奖牌'}}[settings.language]||{} }
function formatMedalRequirement(seconds,language=settings.language){const total=Math.round(seconds*100),whole=String(Math.floor(total/100)).padStart(2,'0'),fraction=String(total%100).padStart(2,'0');return language==='en'?whole+'.'+fraction+' s or less':language==='ja'?whole+'秒'+fraction+'以内':language==='zh'?whole+'.'+fraction+'秒内完成':whole+'초'+fraction+' 이내'}
function medalGoalText(i){const w=medalWords(),t=medalTargetFor(i);return w.target+' · '+w.gold+' '+formatMedalRequirement(t.gold)+' · '+w.silver+' '+formatMedalRequirement(t.silver)+' · '+w.bronze+': '+w.clear}
function updateMedalSelection(){if(menuScreen!=='story')return;const w=medalWords(),buttons=Array.from($('levels').children||[]).slice(-STORY_VISIBLE_COUNT);buttons.forEach((b,i)=>{const tier=medalTier(i);b.setAttribute('data-medal',tier);if(tier){b.textContent=(Math.floor(i/3)+1)+'-'+(i%3+1)+' '+({gold:'🥇',silver:'🥈',bronze:'🥉'}[tier])+(i>data.unlocked?' 🔒':'');b.setAttribute('aria-label',b.textContent+' '+w[tier])}});const box=$('medalSelection'),target=medalTargetFor(level);if(!target){box.classList.add('hidden');return}box.classList.remove('hidden');const language=settings.language,course=(Math.floor(level/3)+1)+'-'+(level%3+1),labels={ko:['메달 획득 조건','초 이내','스테이지 완주'],en:['MEDAL REQUIREMENTS','s or faster','Finish the stage'],ja:['メダル獲得条件','秒以内','ステージクリア'],zh:['奖牌获取条件','秒以内','完成关卡']}[language]||['메달 획득 조건','초 이내','스테이지 완주'];box.textContent=labels[0]+' · '+course+'\n🥇 '+w.gold+'  '+formatMedalRequirement(target.gold)+'\n🥈 '+w.silver+'  '+formatMedalRequirement(target.silver)+'\n🥉 '+w.bronze+'  '+labels[2];box.setAttribute('aria-label',labels[0]+' '+course);}

function showMedalResult(){const box=$('medalResult');box.classList.add('hidden');if(state!=='win'||mode!=='story'||editorTesting)return;const w=medalWords(),tier=medalTier(level),t=medalTargetFor(level),best=data.storyTimes[level]?.best;let text=({gold:'🥇',silver:'🥈',bronze:'🥉'}[tier]||'')+' '+(w[tier]||w.none);if(tier==='gold')text+=' · '+w.best;else if(Number.isFinite(best)){const next=tier==='silver'?'gold':'silver',remaining=Math.max(0,best-t[next]);text+=' · '+w[next]+' '+w.next+' '+remaining.toFixed(2)+' s'}text+='\n'+medalGoalText(level);box.textContent=text;box.setAttribute('data-medal',tier);box.classList.remove('hidden')}
const medalMenu=showMenu;showMenu=function(...args){$('medalResult').classList.add('hidden');$('medalSelection').classList.add('hidden');const out=medalMenu(...args);updateMedalSelection();return out};
const medalFinish=finish;finish=function(...args){const out=medalFinish(...args);showMedalResult();return out};result=finish;
const medalBegin=beginRun;beginRun=function(...args){$('medalResult').classList.add('hidden');$('medalSelection').classList.add('hidden');return medalBegin(...args)};
